from lib import *
S = SS('x48')
steps = [
    step("同步与 Callable。GET /sync:拦截器 preHandle、控制器方法都在同一个线程 http-nio-…-exec-2,postHandle、afterCompletion 都是 REQUEST 派发,拦截器各调用 1 次。GET /callable:控制器方法在 exec-3 上执行,只是返回了 Callable;拦截器打印 afterConcurrentHandlingStarted,原线程释放;Callable 本身在另一个线程 task-1(应用的任务执行器)上执行;完成后请求被重新派发(DispatcherType 变成 ASYNC),在又一个 Tomcat 线程 exec-4 上第二次执行拦截器的 preHandle,随后是 postHandle 和 afterCompletion。一个异步请求,preHandle 被调用了 2 次(REQUEST 和 ASYNC)。", t=tl(S(1)), mark=lidx(S(1), 'afterConcurrentHandlingStarted', 'preHandle [ASYNC]'), done=lidx(S(1), 'GET /sync', '/callable 的 Callable 在 task-1', 'postHandle [ASYNC]'), b=bars([['/sync 里 preHandle 的调用次数', 1, '1'], ['/callable 里 preHandle 的调用次数', 2, '2(REQUEST 与 ASYNC)'], ['/callable 用到的 Tomcat 线程个数', 2, '2(exec-3 与 exec-4)'], ['执行 Callable 的线程', 1, 'task-1(不是 Tomcat 线程)']], 2, mark=[1, 2], done=[0, 3]), kv=KV([['返回 Callable', '原线程立刻释放,Callable 在 task-N 上跑'], ['完成后', '重新派发,DispatcherType=ASYNC'], ['拦截器', 'preHandle 会被调用两次,postHandle 只在 ASYNC 那次'], ['afterConcurrentHandlingStarted', '原线程释放时调用,AsyncHandlerInterceptor 才有']], ['拦截器'])),
    step("DeferredResult 由别人完成。GET /deferred 把 DeferredResult 存进一个 Map 就返回,控制器方法在 exec-2 上执行;发出 0.5 秒后客户端仍在等。另一个请求 /complete(在 exec-3 上)调用 setResult,/deferred 的响应才返回 deferred-ok,总耗时 521 ms;完成后的重新派发又落在 exec-4。第三个例子 /from-timer:自己的线程 my-timer 在 200 ms 后调用 setResult,响应返回(213 ms)。DeferredResult 谁来完成、在哪个线程完成都可以,只要最终有人调用 setResult。", t=tl(S(2)), mark=lidx(S(2), '发出 0.5 秒后'), done=lidx(S(2), '/deferred 最终', '/complete 在', 'my-timer 线程里 setResult', 'GET /from-timer'), b=bars([['发出 0.5 秒后客户端还在等(1=是)', 1, '是'], ['/deferred 总耗时 ms', 521, '521'], ['/from-timer 总耗时 ms', 213, '213']], 521, mark=[0], done=[1, 2]), kv=KV([['返回 DeferredResult', '请求挂起,Tomcat 线程释放'], ['完成者', '另一个请求、定时线程、消息回调都可以'], ['完成后', '重新派发到一个 Tomcat 线程写响应'], ['没人完成', '只能等超时']], ['完成者'])),
    step("超时。全局 spring.mvc.async.request-timeout=1000ms。DeferredResult 自己指定了 500 ms 超时和兜底值:等了 1035 ms 才返回 timeout-fallback,先后调用 onTimeout、onCompletion。DeferredResult(400L) 没有兜底值:等了 829 ms,得到 AsyncRequestTimeoutException(控制器里的 @ExceptionHandler 收到,500)。慢 Callable(3000 ms)被全局 1000 ms 超时打断:1828 ms 后得到 AsyncRequestTimeoutException;Callable 里的 sleep 收到 InterruptedException,线程被中断,不会继续跑完。三个超时的实际等待时间都和设定值对不上。", t=tl(S(3)), mark=lidx(S(3), 'deferred-timeout?ms=500 → 200', '/deferred-timeout-default → 500', '/callable-timeout → 500'), done=lidx(S(3), '被中断了', 'onTimeout 回调'), b=bars([['DeferredResult 设 500 ms,实际等待 ms', 1035, '1035'], ['DeferredResult 设 400 ms,实际等待 ms', 829, '829'], ['慢 Callable,全局设 1000 ms,实际等待 ms', 1828, '1828']], 1828, mark=[0, 1, 2]), kv=KV([['有兜底值', '返回兜底值,不抛异常'], ['没有兜底值', 'AsyncRequestTimeoutException'], ['超时的 Callable', '线程被中断(InterruptedException)'], ['等待时间', '和设定值对不上']], ['超时的 Callable'])),
    step("超时到底有多准。把全局超时放大到 30 秒,对 DeferredResult 设 100 ms、300 ms、700 ms 的超时,每个设定重复 6 次、每次开始前错开一点时间。100 ms 设定的 6 次实际等待 984、864、687、519、333、132 ms;300 ms 设定:1009、862、676、526、327、1158 ms;700 ms 设定:997、862、1688、1524、1337、1149 ms。等待时间随着起点错开而递减,像是超时在固定的 1 秒节拍上才被检测到:设定 100 ms 的请求有时要等将近 1 秒,设定 700 ms 的请求有时要等 1688 ms。节拍的来源这里没有直接验证,只是这组数字的形状。毫秒级的超时靠不住,按秒的粒度用才合理。", t=tl(S(4)), mark=lidx(S(4), '超时 100 ms', '超时 700 ms'), done=lidx(S(4), '超时 300 ms'), b=bars([['设 100 ms 时最长等待 ms', 984, '984'], ['设 300 ms 时最长等待 ms', 1158, '1158'], ['设 700 ms 时最长等待 ms', 1688, '1688'], ['设 100 ms 时最短等待 ms', 132, '132']], 1688, mark=[0, 1, 2], done=[3]), kv=KV([['设 100 ms', '实际 132~984 ms'], ['设 700 ms', '实际 862~1688 ms'], ['规律', '完成时刻对齐到固定节拍,像 1 秒一次的检查'], ['结论', '亚秒级超时不精确,不要依赖']], ['结论'])),
    step("异步里的异常。Callable 里抛 IllegalStateException:异常随结果一起被重新派发到 ASYNC 阶段,在 exec-3 上被控制器里的 @ExceptionHandler 处理,500;拦截器 afterCompletion 在 ASYNC 阶段调用,postHandle 没有。DeferredResult 用 setErrorResult(new IllegalArgumentException)(从 my-timer 线程调用):同样重新派发到 ASYNC,@ExceptionHandler 收到,500。异步里的异常和同步里一样走异常处理器,只是发生在重新派发之后。", t=tl(S(5)), mark=lidx(S(5), '@ExceptionHandler 收到'), done=lidx(S(5), 'callable-ex → 500', 'deferred-ex → 500', 'afterCompletion [ASYNC]'), b=bars([['Callable 抛异常的状态码', 500, '500'], ['setErrorResult 的状态码', 500, '500'], ['异常处理器被调用的次数', 2, '2(各一次)']], 500, done=[0, 1, 2]), kv=KV([['Callable 抛出', '异常带到 ASYNC 派发,走 @ExceptionHandler'], ['setErrorResult', '同上'], ['postHandle', '异常时不调用'], ['afterCompletion', 'ASYNC 阶段调用']], ['Callable 抛出'])),
    step("线程占用。把 Tomcat 的线程数限制为 2。10 个并发的同步慢请求(每个 300 ms):总共 1.58 秒,期间另一个本来很快的 /inflight 请求等了 1161 ms,因为两个线程被慢请求占满。10 个并发的 Callable 慢请求:总共 0.64 秒,/inflight 只等 1 ms。Callable 实际落在 8 个任务线程 task-1 … task-8 上,10 个任务分两批(8 + 2),所以是 0.64 秒而不是单个任务的 300 ms。异步没有让慢操作变快,只是把等待从 Tomcat 线程挪到了另一个池子;那个池子的大小同样会成为瓶颈。", t=tl(S(6)), mark=lidx(S(6), '/sync(每个 300ms)'), done=lidx(S(6), 'Callable 实际执行在 8 个', '/block-sleep(Callable'), b=bars([['同步:10 个慢请求总耗时 ms', 1580, '1580'], ['同步:并发期间 /inflight 等待 ms', 1161, '1161'], ['Callable:10 个慢请求总耗时 ms', 640, '640'], ['Callable:并发期间 /inflight 等待 ms', 1, '1']], 1580, mark=[0, 1], done=[2, 3]), kv=KV([['Tomcat 线程数', '限制为 2'], ['同步慢请求', '占住 Tomcat 线程,其他请求排队'], ['Callable', 'Tomcat 线程释放,别的请求不受影响'], ['代价', '换到 task 线程池(这里 8 个),总吞吐被那个池子限制']], ['代价'])),
]
